  "code": "const fs = require('fs');\n\nfunction logBinomProb(n, k, p) {\n  if (k < 0 || k > n) return -Infinity;\n  let logP = 0;\n  for (let i = 1; i <= k; i++) {\n    logP += Math.log(n - k + i) - Math.log(i);\n  }\n  logP += k * Math.log(p) + (n - k) * Math.log(1 - p);\n  return logP;\n}\n\nfunction binomCDF(n, c, p) {\n  let sum = 0;\n  for (let k = 0; k <= c; k++) {\n    sum += Math.exp(logBinomProb(n, k, p));\n  }\n  return sum;\n}\n\nfunction binomSurvival(n, c, p) {\n  return 1 - binomCDF(n, c, p);\n}\n\nfunction findSamplingPlan(p0, p1, alpha, beta) {\n  let best = null;\n  for (let n = 1; n <= 500; n++) {\n    for (let c = 0; c < n; c++) {\n      const prodRisk = binomSurvival(n, c, p0);\n      const consRisk = binomCDF(n, c, p1);\n      if (prodRisk <= alpha && consRisk <= beta) {\n        return { n, c, prodRisk, consRisk, rejectThreshold: c + 1 };\n      }\n    }\n  }\n  return best;\n}\n\nconst p0 = 0.1;\nconst p1 = 0.2;\nconst alpha = 0.05;\nconst beta = 0.10;\n\nconst plan = findSamplingPlan(p0, p1, alpha, beta);\n\nconst output = {\n  n: plan.n,\n  c: plan.c,\n  prod_risk: plan.prodRisk,\n  cons_risk: plan.consRisk,\n  reject_threshold: plan.rejectThreshold,\n  profit_q2: 0,\n  total_cost_q2: 0,\n  profit_q3: 0,\n  total_cost_q3: 0,\n  profit_q4: 0,\n  total_cost_q4: 0\n};\n\nfs.writeFileSync('numeric_config.json', JSON.stringify({\n  discretization: {},\n  physical: { p0: 0.1, p1: 0.2 },\n  choices: { method: 'single-sampling-plan' },\n  property_set: null\n}, null, 2));\n\nfs.writeFileSync('results.json', JSON.stringify(output, null, 2));\n",
